import{_ as o,l as n,o as e,c as E,v as r,p as l,x as t,d as s,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"交叉汇率三角","description":"","frontmatter":{"title":"交叉汇率三角","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fx-triangle.md","filePath":"quant/fx-triangle.md","lastUpdated":1789023840000}'),d={name:"quant/fx-triangle.md"};function B(m,a,A,c,D,u){const i=n("Mermaid");return e(),E("div",null,[a[1]||(a[1]=r('<h1 id="交叉汇率三角" tabindex="-1">交叉汇率三角 <a class="header-anchor" href="#交叉汇率三角" aria-label="Permalink to &quot;交叉汇率三角&quot;">​</a></h1><div class="epigraph"><p>三种货币只应有两个独立的即期；第三条必须是前两条的乘积，否则三角本身就是一台印钞机——直到价差、延迟与不可兑换把它关掉。</p><footer>—— 无套利会计；高频下的可执行性见 Akram, Rime &amp; Sarno, Journal of International Economics, 2008</footer></div><p><a href="/quant/ppp-anchor">上一课</a>把卡塞尔 PPP 写成名义汇率的长期商品锚；有用的是实际汇率向慢速中枢回复，不适合当周度信号。PPP 不解释交叉报价是否自洽。\\(N\\) 种货币只有 \\(N-1\\) 个独立即期；缺口是交叉必须等于媒介路径乘积，否则存在三角。可执行性受买卖价差、延迟与授信约束；中间价残差多用于清洗，少用于交易。本课写三角作为报价一致性约束，以及它在 NDF、离岸—在岸下如何变形。不重讲半衰期。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(N\\) 种货币有 \\(N(N-1)/2\\) 个货币对，但只有 \\(N-1\\) 个独立汇率（选定计价货币之后）。多余的报价必须与生成树一致。交易系统若把每个货币对当成独立布朗运动去校准波动与相关，造出的协方差矩阵会给三角套利留出正的特征值——那是模型错误，不是交易机会。问题是把一致性写进曲线与风险：即期三角、远期三角、波动三角（交叉的隐含波动由两边与相关决定）是同一逻辑的三层。</p><p>第二层是执行。三角套利不是无风险的三笔同时成交，除非你在同一主经纪商或同一 ECN 上拥有锁定的组合报价。跨平台「看见」的三角，是过时信息。Foucault、Kozhan 与 Tham（2017）讨论有毒套利：吃到过时报价的一方，把延迟当收费。把教科书三角当成稳定 alpha，会变成给更快的人输送流动性。</p><h3 id="标价法与倒数" tabindex="-1">标价法与倒数 <a class="header-anchor" href="#标价法与倒数" aria-label="Permalink to &quot;标价法与倒数&quot;">​</a></h3><p>EURUSD 是一欧元的美元价，USDJPY 是一美元的日元价，乘积才是一欧元的日元价。若有人把 GBPUSD 与 EURGBP 混用倒数，会凭空造出「三角破裂」。所有检查必须先把报价换成同一方向的价格（货币 \\(i\\) 以货币 \\(j\\) 计），再比</p> \\[S_{ik}\\stackrel{?}{=}S_{ij}S_{jk}. \\]<p>买卖价差下，无套利是不等式：买入交叉的卖价，不能低于两条腿买入的合成卖价之外再加费用。点估计的「中间价三角」可以每天都有几个基点的残差，而买卖价差三角仍然成立。</p><p><span class="marginnote">中间价残差用于数据清洗很有用：持续几十个基点的破裂通常是标价反了、小数位错了、或把 NDF 与可交割即期拼在一张表里。不要把它直接当成交易信号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据层：对每个时间戳，用同一来源的买卖报价检查不等式。残差超过阈值先当数据错误，再当机会。风险系统：选一棵生成树（例如所有货币对美元），其余汇率由乘积定义；观测到的交叉与合成交叉之差，列为基差风险，而不是又一个独立因子。这与固定收益里用折现因子生成远期、把存款与期货的差列为凸性或基差是同一思维，见 <a href="/quant/spot-forward-df">即期、远期与折现</a>。</p><p>远期层：CIP 对每个货币对给出远期，三角必须在远期也闭合，否则可用即期三角加掉期合成。交叉货币的流动性薄，市场用两条美元 FX 掉期合成交叉远期，残差进入交叉基差，见 <a href="/quant/irp">利率平价</a> 与 <a href="/quant/xccy-basis">交叉货币基差</a>。波动层：交叉的隐含波动 \\(\\sigma_{ik}^2=\\sigma_{ij}^2+\\sigma_{jk}^2+2\\rho\\sigma_{ij}\\sigma_{jk}\\)（对数汇率、在相关性定义一致时），报价的交叉风险逆转与蝴蝶必须与两边的风险中性相关可对上，否则是波动三角套利（仍受买卖与对冲误差限制）。</p><h3 id="媒介货币与合成" tabindex="-1">媒介货币与合成 <a class="header-anchor" href="#媒介货币与合成" aria-label="Permalink to &quot;媒介货币与合成&quot;">​</a></h3><p>大多数机构客户的交叉盘，银行用美元（或欧元）做媒介内部对冲。客户看到的 EURJPY 报价，已经包含了两条腿的库存与相关风险的加价。三角「破裂」在客户报价上可以是合理的存货溢价。可交易的三角只存在于银行同业或 ECN 的最优买卖之间。研究应使用同层级报价；把对客报价与同业中间价比三角，会得到虚假的稳定利润。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>无套利机制是复制。买 EURJPY 等于买欧元卖日元；若 EURJPY 贵，可卖 EURJPY、买 EURUSD、买 USDJPY（方向按标价调整），现货交割后货币头寸为零。约束生效的速度取决于清算与授信：即期 \\(T+2\\) 交割，三笔必须进同一套额度。资本管制下，某一条腿根本不能交割，复制断了——这正是 <a href="/quant/ndf">NDF</a> 的世界：韩元 NDF 与美元、离岸人民币之间的「三角」不必等于在岸可交割三角。</p><p>微观结构机制是延迟与存货。Lyons 强调做市商用价格管理存货；三角的短暂破裂可以是某一条腿刚吃进大单、尚未更新交叉。更快的相对价值交易者把三条腿重新对齐，赚的是存货调整过程，不是发现了新的宏观信息。这与统计套利里的指数套利同一家族，只是这里的「公平价格」由乘法表给出，而不是由篮子成分。</p><p><span class="marginnote">加密货币交易所上的三角更脏：提币延迟、停牌、记账单位不是同一美元。传统外汇的三角文献不能直接搬到「BTC–ETH–USDT」。本篇只讨论银行间与 ECN 外汇。</span></p><h3 id="波动三角不是即期三角的平方" tabindex="-1">波动三角不是即期三角的平方 <a class="header-anchor" href="#波动三角不是即期三角的平方" aria-label="Permalink to &quot;波动三角不是即期三角的平方&quot;">​</a></h3><p>相关 \\(\\rho\\) 可以变。欧元—日元的隐含相关在风险偏好崩溃时会跳，交叉波动的「公平」值跟着动。用历史相关去算交叉的理论隐含波动，再当三角套利，会把相关风险当成 alpha。正确做法是把交叉期权与两边期权联立，解出风险中性相关，再问报价是否离开这个曲面足够远、且你能对冲三条 vega。没有期权账簿时，不要做波动三角。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不可兑换、在岸午盘停报、央行干预、fixing 窗口，都会让某一条腿的可交易性下降，三角不等式的前提消失。伦敦下午与纽约重叠时段，美元媒介最深，三角最紧；亚洲早盘交叉更宽。回测若用每分钟中间价、假设三腿同时成交于中间，会高估几个数量级。应至少用买卖价、假设吃价、并加一条保守延迟。</p><p>风险管理不要把 EUR、USD、JPY 的即期风险当三个独立 01。一致的做法是持有 \\(N-1\\) 个美元交叉的风险，交叉盘自动映射。否则同一欧元空头会在 EURUSD 与 EURJPY 上被算两次，或对冲时买错腿。</p><p><span class="marginnote">Deardorff（1979）指出单向套利（用商品或证券市场绕过外汇）会进一步收紧平价带。对 G10 即期，这一层通常已被价差覆盖；对有资本管制的货币，单向路径（通过不可交割、通过离岸存款）才是真正的边界，应与 NDF 篇一起读。</span></p>',26)),(e(),l(h,null,{default:t(()=>[p(i,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20TD%0A%20%20USD%5B%22USD%20%E4%BD%9C%E4%B8%BA%E5%AA%92%E4%BB%8B%22%5D%20--%3E%20EUSD%5B%22EURUSD%22%5D%0A%20%20USD%20--%3E%20UJPY%5B%22USDJPY%22%5D%0A%20%20EUSD%20--%3E%20SYN%5B%22%E5%90%88%E6%88%90%20EURJPY%22%5D%0A%20%20UJPY%20--%3E%20SYN%0A%20%20MKT%5B%22%E5%B8%82%E5%9C%BA%20EURJPY%20%E6%8A%A5%E4%BB%B7%22%5D%20--%3E%20CMP%5B%22%E4%B9%B0%E5%8D%96%E4%BB%B7%E5%B7%AE%E5%86%85%E6%AF%94%E8%BE%83%22%5D%0A%20%20SYN%20--%3E%20CMP%0A%20%20CMP%20--%3E%7C%E4%B8%8D%E7%AD%89%E5%BC%8F%E7%A0%B4%E8%A3%82%E4%B8%94%E5%8F%AF%E9%94%81%E5%AE%9A%7C%20ARB%5B%22%E4%B8%89%E8%A7%92%E6%89%A7%E8%A1%8C%22%5D%0A%20%20CMP%20--%3E%7C%E4%B8%AD%E9%97%B4%E4%BB%B7%E5%B0%8F%E6%AE%8B%E5%B7%AE%7C%20DATA%5B%22%E6%95%B0%E6%8D%AE%E6%88%96%E5%AD%98%E8%B4%A7%E5%99%AA%E5%A3%B0%22%5D%0A%20%20NDF%5B%22%E4%B8%8D%E5%8F%AF%E4%BA%A4%E5%89%B2%E8%85%BF%22%5D%20--%3E%20BRK%5B%22%E5%A4%8D%E5%88%B6%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(N\\) 种货币只有 \\(N-1\\) 个独立即期；交叉必须等于媒介路径乘积，否则存在三角。</li><li>可执行性受买卖价差、延迟与授信约束；中间价残差多用于清洗，少用于交易（Akram, Rime and Sarno, 2008）。</li><li>远期三角与 CIP、交叉基差是同一致性的到期版本；波动三角还依赖隐含相关，不能只用历史相关。</li><li>资本管制下 NDF 与在岸不必闭合三角；那是市场分割，不是免费印钞。</li><li>风险应在生成树上记账，避免交叉盘与媒介盘重复计算。</li><li>出处：Akram, Rime and Sarno, <em>Journal of International Economics</em>, 2008；Lyons, <em>The Microstructure Approach to Exchange Rates</em>, 2001；Deardorff, <em>Journal of Political Economy</em>, 1979；Foucault, Kozhan and Tham, <em>Review of Financial Studies</em>, 2017；CIP 背景见 Keynes, 1923 与 Fama, 1984。</li></ul>',2))])}const _=o(d,[["render",B]]);export{f as __pageData,_ as default};
